package org.zawamod.zawa.world.block.entity;
import net.minecraft.core.BlockPos; import net.minecraft.world.entity.player.Inventory; import net.minecraft.world.inventory.AbstractContainerMenu; import net.minecraft.world.level.block.state.BlockState; import org.zawamod.zawa.world.inventory.IncubatorMenu;
public class IncubatorBlockEntity extends ZawaContainerBlockEntity { public IncubatorBlockEntity(BlockPos p,BlockState s){super(ZawaBlockEntities.INCUBATOR.get(),p,s,3);} @Override protected AbstractContainerMenu createMenu(int id,Inventory inv){return new IncubatorMenu(id,inv,this,new net.minecraft.world.inventory.SimpleContainerData(2));} @Override public void tickServer(){if(level==null||level.isClientSide)return;boolean ready=!items.get(0).isEmpty()&&!items.get(1).isEmpty()&&items.get(2).isEmpty();if(ready){active=true;if(++progress>=totalProgress){progress=0;active=false;items.set(2,items.get(0).copyWithCount(1));items.get(0).shrink(1);items.get(1).shrink(1);setChanged();}}else if(active){active=false;progress=0;setChanged();}} }
